import Foundation

public struct GenerationOptions {
    /// Modules to import in the generated file, for example `SharedKt`, `AppMapping`.
    public var imports: [String]
    /// Modules to import with `@testable`, for example `MyApp`.
    public var testableImports: [String]
    /// Rules to leave out, by name.
    public var excluded: Set<String>
    /// Only these Rules, when not empty.
    public var only: Set<String>
    public var maxEvaluationsPerRule: Int

    public init(
        imports: [String], testableImports: [String], excluded: Set<String> = [], only: Set<String> = [],
        maxEvaluationsPerRule: Int = 500
    ) {
        self.imports = imports
        self.testableImports = testableImports
        self.excluded = excluded
        self.only = only
        self.maxEvaluationsPerRule = maxEvaluationsPerRule
    }
}

public struct GenerationResult {
    public var source: String
    public var generated: [String]
    public var skipped: [(rule: String, reason: String)]
    /// Per type: cases or conformers that could not be built, so the domain is partial.
    public var dropped: [String: [String]]
}

public enum RuleGenerator {
    public static func generate(rules: [RuleInfo], index: TypeIndex, options: GenerationOptions) -> GenerationResult {
        let builder = DomainBuilder(index: index)
        var generated: [(rule: String, domain: String)] = []
        var skipped: [(rule: String, reason: String)] = []
        var seen: Set<String> = []

        for rule in rules where seen.insert(rule.name).inserted {
            if !options.only.isEmpty, !options.only.contains(rule.name) { continue }
            if options.excluded.contains(rule.name) { skipped.append((rule.name, "excluded")); continue }
            if rule.isPrivate { skipped.append((rule.name, "private Rule")); continue }
            if rule.isGeneric { skipped.append((rule.name, "generic Rule")); continue }
            let pool = ValuePool(id: rule.name, ints: rule.ints, doubles: rule.doubles, strings: rule.strings)
            index.visibleModules = Set(rule.imports + [rule.module].compactMap { $0 })
            index.ruleModule = rule.module
            index.reachableModules = Set(options.imports + options.testableImports)
            do {
                let built = try builder.domain(for: rule.name, scope: nil, pool: pool)
                generated.append((rule.name, built.name))
            } catch let error as Unsupported {
                skipped.append((rule.name, error.reason))
            } catch {
                skipped.append((rule.name, "\(error)"))
            }
        }

        var lines = [
            "// Generated by sfgen from the Rules' own sources and the compiler's symbol graphs. Do not edit; regenerate.",
            "// Each test builds a domain from the Rule's literals and constructible input types, then checks with `Prove` that",
            "// the Rule is total and deterministic over it.",
            "",
        ]
        lines += options.imports.sorted().map { "import \($0)" }
        lines += ["import Foundation", "import SwiftFormal", "import SwiftFormalTesting", "import Testing"]
        lines += options.testableImports.sorted().map { "@testable import \($0)" }
        lines += harness(maxEvaluations: options.maxEvaluationsPerRule)
        lines += [
            "// MARK: - Domains",
            "",
        ]
        lines += builder.declarations
        lines += [
            "", "// MARK: - Rules", "", "@MainActor", "@Suite(\"SwiftFormal generated Rule checks\")", "struct SwiftFormalGeneratedRules {",
        ]
        for item in generated {
            lines += [
                "    // sfgen:rule \(item.rule)",
                "    @Test(\"\(item.rule)\") func test\(sanitized(item.rule))() { sfCheck(\"\(item.rule)\", \(item.domain)) }",
            ]
        }
        lines += ["}", ""]
        return GenerationResult(
            source: lines.joined(separator: "\n"), generated: generated.map(\.rule), skipped: skipped, dropped: builder.dropped
        )
    }

    /// The helpers every generated file starts with: `sfCheck`, which walks one Rule with `Prove`, and `sfDescribe`.
    static func harness(maxEvaluations: Int) -> [String] {
        [
            "",
            "@MainActor",
            "private func sfCheck<R: Rule>(",
            "    _ name: String, _ makeDomain: @autoclosure () -> Domain<R>, sourceLocation: SourceLocation = #_sourceLocation",
            ") {",
            "    print(\"SFGEN-BEGIN\\t\\(name)\"); fflush(stdout)",
            "    let domain = makeDomain()",
            "    let report = Prove(",
            "        name, it: { (rule: R) in sfDescribe(rule.execute()) }, over: domain,",
            "        budget: Budget(maxEvaluations: \(maxEvaluations)), allowBounded: true, sourceLocation: sourceLocation",
            "    ) { Deterministic() }.report",
            "    let verdict = report.isProved ? \"proved\" : report.hasNoCounterexample ? \"bounded\" : \"FAILED\"",
            "    print(\"SFGEN\\t\\(name)\\t\\(domain.count)\\t\\(verdict)\"); fflush(stdout)",
            "}",
            "",
            "/// An output as text, with object addresses (`0x…`) and UUIDs masked: a new object or identifier on each call is",
            "/// not a change of behaviour.",
            "private func sfDescribe<Output>(_ value: Output) -> String {",
            "    String(describing: value)",
            "        .replacingOccurrences(of: \"0x[0-9A-Fa-f]{6,}\", with: \"0x*\", options: .regularExpression)",
            "        .replacingOccurrences(",
            "            of: \"[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\", with: \"<uuid>\",",
            "            options: .regularExpression)",
            "}",
            "",
        ]
    }

    static func sanitized(_ name: String) -> String { name.map { $0.isLetter || $0.isNumber ? String($0) : "_" }.joined() }
}

/// Given compiler errors in a generated file, finds the Rules whose tests cannot compile, so the next
/// generation leaves them out. An error inside a shared domain declaration removes every Rule that uses it.
public enum Pruner {
    public static func rulesToExclude(generated: String, errorLines: [Int]) -> Set<String> {
        let lines = generated.components(separatedBy: "\n")
        var references: [String: Set<String>] = [:]
        var declaredAt: [Int: String] = [:]
        var ruleAt: [Int: String] = [:]
        var currentRule: String?
        for (offset, line) in lines.enumerated() {
            let number = offset + 1
            if line.hasPrefix("private let sfd_"), let name = line.dropFirst("private let ".count).split(separator: ":").first {
                declaredAt[number] = String(name)
                references[String(name)] = names(in: String(line.dropFirst("private let ".count + name.count)))
            }
            if let marker = line.range(of: "// sfgen:rule ") { currentRule = String(line[marker.upperBound...]) }
            if line.contains("@Test("), let rule = currentRule {
                ruleAt[number] = rule
                references["rule:\(rule)"] = names(in: line)
            }
        }
        var broken: Set<String> = []
        var excluded: Set<String> = []
        for error in errorLines {
            if let name = declaredAt[error] {
                broken.insert(name)
            } else if let rule = ruleAt[error] ?? ruleAt[error - 1] ?? ruleAt[error + 1] {
                excluded.insert(rule)
            }
        }
        func uses(_ start: String, _ target: Set<String>, _ visited: inout Set<String>) -> Bool {
            guard visited.insert(start).inserted else { return false }
            if target.contains(start) { return true }
            return (references[start] ?? []).contains { uses($0, target, &visited) }
        }
        for key in references.keys where key.hasPrefix("rule:") {
            var visited: Set<String> = []
            if uses(key, broken, &visited) { excluded.insert(String(key.dropFirst(5))) }
        }
        return excluded
    }

    private static func names(in text: String) -> Set<String> {
        var result: Set<String> = []
        var rest = text[...]
        while let range = rest.range(of: "sfd_") {
            let digits = rest[range.upperBound...].prefix(while: \.isNumber)
            result.insert("sfd_\(digits)")
            rest = rest[range.upperBound...]
        }
        return result
    }
}
